content:
:root {
  --primary: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: 20px;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.header {
  text-align: center;
  margin-bottom: 8px;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 4px;
}

.subtitle {
  font-size: 1rem;
  color: var(--text-muted);
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.chart-container {
  width: 100%;
  height: 400px;
}

.table-container {
  width: 100%;
  overflow-x: auto;
  border-radius: 8px;
  border: 1px solid var(--border-color);
}

.controls {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 16px;
}

.btn {
  background-color: #f1f5f9;
  color: var(--text-muted);
  border: 1px solid var(--border-color);
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn:hover {
  background-color: #e2e8f0;
  color: var(--text-main);
}

.btn:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.btn-active {
  background-color: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
}

.btn-active:hover {
  background-color: var(--primary-hover);
  color: #ffffff;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
}

.data-table th,
.data-table td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-color);
}

.data-table th {
  background-color: #f8fafc;
  font-weight: 600;
  color: var(--text-main);
}

.data-table tr:hover {
  background-color: #f8fafc;
}

@media (max-width: 768px) {
  body {
    padding: 12px;
  }

  .title {
    font-size: 1.5rem;
  }

  .subtitle {
    font-size: 0.875rem;
  }

  .card {
    padding: 16px;
    gap: 12px;
  }

  .chart-container {
    height: 300px;
  }

  .btn {
    padding: 6px 12px;
    font-size: 0.8rem;
  }

  .data-table {
    font-size: 0.85rem;
  }

  .data-table th,
  .data-table td {
    padding: 8px 12px;
  }
}

export const STORES = ['渋谷店', '新宿店', '銀座店'] as const;

export type StoreKey = typeof STORES[number];

export type MonthlyData = {
  month: string;
  渋谷店: number;
  新宿店: number;
  銀座店: number;
};

import { ResponsiveContainer, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend } from 'recharts';
import { MonthlyData, StoreKey } from '../types';
import '../index.css';

interface StoreChartProps {
  data: MonthlyData[];
  selectedStore: StoreKey | 'すべて';
}

const storeColors: Record<StoreKey, string> = {
  '渋谷店': '#3b82f6',
  '新宿店': '#10b981',
  '銀座店': '#f59e0b',
};

export default function StoreChart({ data = [], selectedStore = 'すべて' }: StoreChartProps) {
  return (
    <div className="chart-container">
      <ResponsiveContainer width="100%" height="100%">
        <LineChart data={data} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
          <XAxis dataKey="month" stroke="#64748b" />
          <YAxis stroke="#64748b" tickFormatter={(value: number) => value.toLocaleString()} />
          <Tooltip 
            formatter={(value: number) => [`${value.toLocaleString()} 人`, '']}
            contentStyle={{ backgroundColor: '#ffffff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }}
          />
          <Legend />
          {(selectedStore === 'すべて' || selectedStore === '渋谷店') && (
            <Line 
              type="monotone" 
              dataKey="渋谷店" 
              stroke={storeColors['渋谷店']} 
              strokeWidth={3} 
              activeDot={{ r: 8 }} 
            />
          )}
          {(selectedStore === 'すべて' || selectedStore === '新宿店') && (
            <Line 
              type="monotone" 
              dataKey="新宿店" 
              stroke={storeColors['新宿店']} 
              strokeWidth={3} 
              activeDot={{ r: 8 }} 
            />
          )}
          {(selectedStore === 'すべて' || selectedStore === '銀座店') && (
            <Line 
              type="monotone" 
              dataKey="銀座店" 
              stroke={storeColors['銀座店']} 
              strokeWidth={3} 
              activeDot={{ r: 8 }} 
            />
          )}
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}

import { useState } from 'react';
import { MonthlyData, StoreKey } from './types';
import { initialData } from './constants';
import StoreChart from './components/StoreChart';
import './index.css';

export default function App() {
  const [data] = useState<MonthlyData[]>(initialData);
  const [selectedStore, setSelectedStore] = useState<StoreKey | 'すべて'>('すべて');
  const unit = '人';

  const stores: (StoreKey | 'すべて')[] = ['すべて', '渋谷店', '新宿店', '銀座店'];

  const formatValue = (val: number) => `${val.toLocaleString()} ${unit}`;

  const visibleStores = selectedStore === 'すべて' ? (['渋谷店', '新宿店', '銀座店'] as const) : ([selectedStore] as const);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">店舗別月別来客数比較</h1>
        <p className="subtitle">渋谷店・新宿店・銀座店の年間来客数トレンドを可視化します</p>
      </header>

      <div className="card">
        <div className="controls">
          {stores.map((store) => (
            <button
              key={store}
              className={`btn ${selectedStore === store ? 'btn-active' : ''}`}
              onClick={() => setSelectedStore(store)}
              aria-pressed={selectedStore === store}
            >
              {store}
            </button>
          ))}
        </div>

        <StoreChart data={data} selectedStore={selectedStore} />
      </div>

      <div className="card">
        <h2 style={{ fontSize: '1.25rem', fontWeight: 600, color: 'var(--text-main)' }}>月別来客数データ一覧</h2>
        <div className="table-container">
          <table className="data-table">
            <thead>
              <tr>
                <th>月</th>
                {visibleStores.map((store) => (
                  <th key={store}>{store}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {data.map((row) => (
                <tr key={row.month}>
                  <td>{row.month}</td>
                  {visibleStores.map((store) => (
                    <td key={store}>{formatValue(row[store])}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
